insert into public.translations (locale, key, value) values
  ('pt-BR', 'skills.hub.title', $json$"Instalar do skills.sh"$json$::jsonb),
  ('en', 'skills.hub.title', $json$"Install from skills.sh"$json$::jsonb),
  ('es', 'skills.hub.title', $json$"Instalar desde skills.sh"$json$::jsonb),
  ('zh-CN', 'skills.hub.title', $json$"从 skills.sh 安装"$json$::jsonb),
  ('hi', 'skills.hub.title', $json$"skills.sh से इंस्टॉल करें"$json$::jsonb),
  ('ar', 'skills.hub.title', $json$"التثبيت من skills.sh"$json$::jsonb),
  ('fr', 'skills.hub.title', $json$"Installer depuis skills.sh"$json$::jsonb),
  ('ru', 'skills.hub.title', $json$"Установить из skills.sh"$json$::jsonb),
  ('ja', 'skills.hub.title', $json$"skills.sh からインストール"$json$::jsonb),
  ('de', 'skills.hub.title', $json$"Von skills.sh installieren"$json$::jsonb),
  ('pt-BR', 'skills.hub.description', $json$"Busque no diretório aberto de skills (skills.sh) e instale uma skill com um clique. Ela vira uma skill comum neste computador: dá para desligá-la ou removê-la, e o Jev a escolhe como qualquer outra."$json$::jsonb),
  ('en', 'skills.hub.description', $json$"Search the open skills directory (skills.sh) and install a skill with one click. It becomes a regular skill on this computer: you can turn it off or remove it, and Jev picks it like any other."$json$::jsonb),
  ('es', 'skills.hub.description', $json$"Busca en el directorio abierto de skills (skills.sh) e instala una skill con un clic. Se convierte en una skill normal en este equipo: puedes desactivarla o eliminarla, y Jev la elige como cualquier otra."$json$::jsonb),
  ('zh-CN', 'skills.hub.description', $json$"在开放的技能目录（skills.sh）中搜索，一键安装技能。它会成为这台电脑上的普通技能：可以关闭或删除，Jev 会像选择其他技能一样选择它。"$json$::jsonb),
  ('hi', 'skills.hub.description', $json$"खुली स्किल डायरेक्टरी (skills.sh) में खोजें और एक क्लिक में स्किल इंस्टॉल करें। यह इस कंप्यूटर पर एक सामान्य स्किल बन जाती है: आप इसे बंद या हटा सकते हैं, और Jev इसे किसी भी अन्य की तरह चुनता है।"$json$::jsonb),
  ('ar', 'skills.hub.description', $json$"ابحث في دليل المهارات المفتوح (skills.sh) وثبّت مهارة بنقرة واحدة. تصبح مهارة عادية على هذا الكمبيوتر: يمكنك إيقافها أو إزالتها، ويختارها Jev مثل أي مهارة أخرى."$json$::jsonb),
  ('fr', 'skills.hub.description', $json$"Cherchez dans l’annuaire ouvert de skills (skills.sh) et installez une skill en un clic. Elle devient une skill ordinaire sur cet ordinateur : vous pouvez la désactiver ou la supprimer, et Jev la choisit comme les autres."$json$::jsonb),
  ('ru', 'skills.hub.description', $json$"Ищите в открытом каталоге навыков (skills.sh) и устанавливайте навык одним щелчком. Он становится обычным навыком на этом компьютере: его можно выключить или удалить, а Jev выбирает его как любой другой."$json$::jsonb),
  ('ja', 'skills.hub.description', $json$"オープンなスキルディレクトリ（skills.sh）を検索して、ワンクリックでスキルをインストールします。このコンピューター上の通常のスキルになり、オフにしたり削除したりでき、Jev は他のスキルと同じように選びます。"$json$::jsonb),
  ('de', 'skills.hub.description', $json$"Durchsuchen Sie das offene Skill-Verzeichnis (skills.sh) und installieren Sie einen Skill mit einem Klick. Er wird zu einem normalen Skill auf diesem Computer: Sie können ihn ausschalten oder entfernen, und Jev wählt ihn wie jeden anderen."$json$::jsonb),
  ('pt-BR', 'skills.hub.placeholder', $json$"Buscar skills, p. ex.: pdf, notas de versão, testes"$json$::jsonb),
  ('en', 'skills.hub.placeholder', $json$"Search skills, e.g. pdf, release notes, testing"$json$::jsonb),
